let shapes;
let minWH, d;
// let layGr, layLUT;

function setup() {
	let w, h;
	if (windowWidth > windowHeight) {
		w = windowWidth;
		h = floor(w * 3 / 4);
	} else {
		h = windowHeight;
		w = floor(h * 3 / 4);
	}
	createCanvas(w, h);
	pixelDensity(2)
	describe("curved dashed lines with various thickness and colors")

	// global vars
	minWH = max(width, height);

	// layGr = createGraphics(width, height)
	noFill()
	stroke(212) // 232
	strokeWeight(2)
	strokeCap(SQUARE);

	shapes = [];
	for (let i = 0; i < 3; i++) {		
		d = getRandDiameter()
		shapes.push(new NEdge(0, 0, d))
		d = getRandDiameter()
		shapes.push(new NEdge(width, 0, d))
		d = getRandDiameter()
		shapes.push(new NEdge(width, height, d))
		d = getRandDiameter()
		shapes.push(new NEdge(0, height, d))

		// remove random shape
		shapes.splice(~~random(shapes.length), 1)
	}

}

function getRandDiameter() {
	return random(minWH * 0.45, minWH * 0.75);
}


function draw() {
	blendMode(BLEND)
	background(0);
	background("beige");
	// blendMode(DIFFERENCE)
	// translate(-width * 0.5, -height * 0.5)


	noFill()
	stroke(255)
	for (let s of shapes) {
		s.show(random(2, 6), ~~random(4, minWH * 0.02))
	}

	/*
	noStroke()
	fill(32)
	blendMode(BLEND)
	circle(width * 0.5, height * 0.5, d);
	*/
	// blendMode(DIFFERENCE)
	stroke(255)
	noFill()

	const num = random(2, 6)
	const cx = random(-width * 0.2, width * 1.2)
	const cy = random(-height * 0.2, height * 1.2)
	d = getRandDiameter() * 1.5
	for (let i = 0; i < num; i++) {
		// fill(random(160, 255))
		randomStroke()
		const dx = random(d * 0.01, d * 0.025);
		const dy = random(d * 0.01, d * 0.025);
		circle(cx + random(-dx, dx), cy + random(-dy, dy), d);
	}

	// image(layGr, 0, 0)
	// drawLUT()
	// Idea: taking LT to color grayscale image, 
  //       but shader only in WEBGL, linedash only in 2D

	// frame
	noFill()
	stroke("rgba(245,245,220,0.82)")
	drawingContext.setLineDash([])
	const pad = minWH * 0.05;
	strokeWeight(pad)
	rect(0, 0, width, height)
	rect(0, 0, width, height, pad * 0.75)
	// rect(0, 0, width, height, pad * 0.5)

	// noLoop() removed for animation
}

function drawLUT() {
	push()
	blendMode(BLEND)
	const ctx = drawingContext;

	const gradient = ctx.createLinearGradient(0, 0, 0, 100);

	gradient.addColorStop(0, "beige"); // "navy"
	gradient.addColorStop(0.01, color(random(512), random(128), random(255)));
	var num = random(0, 4);
	for (let i = 0; i < num; i++) {
		const clr = color(random(512), random(128), random(255));
		gradient.addColorStop(random(1), clr);
	}
	gradient.addColorStop(1, color(random(512), random(128), random(255)));

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, 25, 100);
	pop()
}

function mouseClicked() {
	// if (mouseButton === LEFT) loop()
	setup()
	loop()
	// console.log(frameCount)
}

function randomStroke() {
	strokeWeight(~~random(10,200));
	const n = ~~random(1, 4)
	const list = []
	for (let i = 0; i < n; i++) {
		list.push(~~random(2, random(2, 200)))
	}
	drawingContext.setLineDash(list);

	stroke(random(255), random(100), random(255), random(150, 255))
	// stroke(random(255), random(150, 255))
}

class NEdge {
	constructor(x, y, d = 10) {
		this.x = x;
		this.y = y;
		this.d = d;

		this.pts = []
		for (let i = 0; i < 3; i++) {
			var dx = random(d * 0.5, d);
			var dy = random(d * 0.5, d);
			const sx = Math.sign(sin(i * TWO_PI/4))
			const sy = Math.sign(cos(i * TWO_PI/4))
			this.pts.push({x: sx * dx, y: sy * dy})
		}

		// palette
		const palettes = [
			["#e96d5e", "#ff9760", "#ffe69d", "#6a7e6a", "#393f5f"],
			["#af43be", "#fd8090", "#c4ffff", "#08deea", "#1261d1"],
			["#a0ffe3", "#65dc98", "#8d8980", "#575267", "#222035"],
			["#ff2a6d", "#d1f7ff", "#f5d9e8", "#005678", "#01012b"],
			["#8f704b", "#daae6d", "#89e3f6", "#4d9e9b", "#44786a"],
			["#b0acb0", "#e2dddf", "#85ebd9", "#3d898d", "#2f404d"],
			["#ff184c", "#ff577d", "#ffccdc", "#0a9cf5", "#003062"],
		]
		this.p = random() < 0.8 ? palettes[5] : random(palettes);
	}

	show(n = 1, d = 0) {
		push()
		for (let i = 0; i < n; i++) {			
			curveTightness(random())
			randomStroke()
			var clr = color(this.p[i % this.p.length])
			clr.setAlpha(228)
			stroke(clr)
			beginShape()

			if (true) {
				for (let p of this.pts) {
					var dx = random(-d, d);
					var dy = random(-d, d);
					vertex(this.x + p.x + dx, this.y + p.y + dy)
				}
			}

			if (true) {
				for (let i = 0; i < this.pts.length + 2; i++) {
					const p = this.pts[i % this.pts.length];
					var dx = random(-d, d);
					var dy = random(-d, d);
					curveVertex(this.x + p.x + dx, this.y + p.y + dy)
				}
			}

			endShape(CLOSE)
		}
		pop()
	}
}
